static Json prop(const Json& j,const char* k){return j.is_object()&&j.contains(k)?j[k]:Json();}
static std::string string(const Json& j,const std::string& fallback=""){if(j.is_string())return j.get<std::string>();if(j.is_number()||j.is_boolean())return j.dump();return fallback;}
static std::string slug(std::string s){std::string o;bool separator=false;for(unsigned char c:s){if(c<128&&std::isalnum(c)){if(separator&&!o.empty())o+='-';o+=char(std::tolower(c));separator=false;}else separator=true;}return o.empty()?"garment":o;}
static std::string join(const Json& a,const std::string& delimiter){std::string o;if(!a.is_array())return o;for(auto& v:a){if(!o.empty())o+=delimiter;o+=string(v);}return o;}
static std::string display(const Json& j,const std::string& fallback){return j.is_null()?fallback:string(j,fallback);}
static Json sizesOf(const Json& p){Json grading=prop(p,"grading");Json sizes=prop(grading,"sizes");return sizes.is_array()?sizes:Json::array({display(prop(grading,"baseSize"),"M")});}
