static Json arr(const Json& j,const char* key){auto v=prop(j,key);return v.is_array()?v:Json::array();}
static double numeric(const Json& j,double fallback=0){if(j.is_number())return j.get<double>();if(j.is_boolean())return j.get<bool>()?1:0;if(j.is_string()){try{return std::stod(j.get<std::string>());}catch(...){}}return fallback;}
static double number(const Json& j,const char* key,double fallback=0){auto v=prop(j,key);return v.is_null()?fallback:numeric(v,fallback);}
static std::string fixed(double n,int digits){std::ostringstream out;out<<std::fixed<<std::setprecision(digits)<<n;return out.str();}
static std::string cell(const std::string& s){std::string result="\"";for(char c:s){if(c=='\"')result+='\"';result+=c;}return result+'\"';}
using Rows=std::vector<std::vector<std::string>>;
static std::string csv(const Rows& rows){std::string result;for(size_t i=0;i<rows.size();i++){if(i)result+='\n';for(size_t k=0;k<rows[i].size();k++){if(k)result+=',';result+=cell(rows[i][k]);}}return result;}
